def put(n,steps,errors,solution=None):
 author.add('LA7',f'005-{n:03}',steps,errors,'核对全部小问、特征方程、特征空间、正交归一、合同变换及边界条件。')
 p=author.PATCHES[f'SRC-LA7-E005-{n:03}'];p['supersedes_computed_supplement']=True
 if solution is not None:p['solution']=solution
def example(n,steps,errors):
 author.add_example('LA7',n,steps,errors,'逐步计算并以精确代数核验特征关系、正交性或二次型变换。')
 author.PATCHES['SRC-LA7-X'+n]['supersedes_computed_supplement']=True

def gram_schmidt(A,label):
 assert A.rank()==A.cols
 out=[f'**{label}。** 将原向量按列排成 $$A='+L(A)+r'.$$依次取正交方向 $b_j=a_j-\sum_{i<j}(a_j^Tb_i)/(b_i^Tb_i)b_i$，最后逐列单位化。投影分母必须使用bᵢ自身的模平方。']
 orth=[];units=[]
 for j in range(A.cols):
  a=A[:,j];b=a.copy();terms=[]
  for i,v in enumerate(orth):
   num=(a.T*v)[0];den=(v.T*v)[0];c=sp.simplify(num/den);b-=c*v
   terms.append(r'\frac{a_{'+str(j+1)+'}^Tb_{'+str(i+1)+r'}}{b_{'+str(i+1)+'}^Tb_{'+str(i+1)+r'}}=\frac{'+L(num)+'}{'+L(den)+'}='+L(c))
  b=sp.simplify(b);s=sp.simplify((b.T*b)[0]);assert s>0
  u=sp.simplify(b/sp.sqrt(s));orth.append(b);units.append(u)
  if terms:out+=['第'+str(j+1)+'步各个投影系数：$$'+r',\quad '.join(terms)+'.$$']
  out+=['扣掉这些投影，得到 $$b_{'+str(j+1)+'}='+L(b)+r',\quad \|b_{'+str(j+1)+r'}\|^2='+L(s)+r',\quad q_{'+str(j+1)+'}='+L(u)+'.$$']
 Q=sp.Matrix.hstack(*units);assert sp.simplify(Q.T*Q)==sp.eye(A.cols)
 assert A.row_join(Q).rank()==A.rank()
 out+=['按次序拼成 $$Q='+L(Q)+r',\quad Q^TQ='+L(sp.simplify(Q.T*Q))+r'.$$所以各列两两正交且均为单位向量。每一步仅扣除前面方向并作非零倍乘，张成空间不变。']
 return out,Q

def eigen_work(A,label,diagonalize=False,orthogonal=False,order=None):
 t=sp.Symbol('lambda');M=t*sp.eye(A.rows)-A;poly=sp.factor(M.det());ev=A.eigenvects()
 if order is not None:ev=sorted(ev,key=lambda entry:order.index(entry[0]))
 out=[f'**{label}。** 非零向量v满足Av=λv，当且仅当(λI−A)v=0。因此先求特征方程。']+determinant(M)
 out+=[r'整理因式：$$\det(\lambda I-A)='+L(poly)+r'=0.$$根的次数是代数重数；还须逐个解齐次组，不能直接把重数当作独立特征向量个数。']
 cols=[];values=[]
 for value,multiplicity,basis in ev:
  B=sp.Matrix.hstack(*basis)
  out+=[r'取 $$\lambda='+L(value)+r'$$，其代数重数为'+str(multiplicity)+'。']+system(A-value*sp.eye(A.rows),sp.zeros(A.rows,1),'求对应特征空间')
  out+=[r'可取该空间的一组基 $$B_{\lambda}='+L(B)+r'.$$全部特征向量是这些基向量的任意非零线性组合；系数不得全0。特征空间维数为'+str(len(basis))+'。']
  assert A*B==value*B
  if orthogonal:
   steps,B=gram_schmidt(B,'在本特征空间内部正交归一');out+=steps
  cols.extend([B[:,j] for j in range(B.cols)]);values.extend([value]*B.cols)
 if diagonalize or orthogonal:
  if len(cols)<A.rows:
   out+=['全部特征空间维数之和为'+str(len(cols))+'，小于阶数'+str(A.rows)+'，无法凑成一组特征向量基，故不可相似对角化。']
  else:
   P=sp.Matrix.hstack(*cols);D=sp.diag(*values);assert P.det()!=0 and sp.simplify(A*P-P*D)==sp.zeros(A.rows)
   out+=['按以上顺序拼各特征向量为 $$P='+L(P)+r',\quad \Lambda='+L(D)+r',\quad \det P='+L(sp.simplify(P.det()))+r'\ne0.$$逐列Avᵢ=λᵢvᵢ给AP=PΛ，左乘P⁻¹得到所需P⁻¹AP=Λ。']
   if orthogonal:
    assert sp.simplify(P.T*P)==sp.eye(A.rows)
    out+=[r'实对称矩阵不同特征值的特征向量自动正交，同一特征空间内部已用施密特法处理，所以 $$P^TP=I,\quad P^{-1}=P^T,\quad P^TAP=\Lambda.$$']
   return out,P,D
 return out,None,None

def congruence(A,C,label,orthogonal=False):
 D=sp.simplify(C.T*A*C);assert C.det()!=0 and D.is_diagonal()
 out=[fr'**{label}。** 按列写出原变量到新变量的逆代换 $$x=Cy,\quad C='+L(C)+r',\quad\det C='+L(sp.simplify(C.det()))+r'\ne0.$$']
 out+=multiply(C.T,A,r'C^TA')+multiply(C.T*A,C,r'C^TAC')
 out+=['故 $$f=x^TAx=y^T(C^TAC)y=y^T'+L(D)+r'y.$$对角元就是各新变量平方项的系数，没有交叉项。']
 if orthogonal:
  assert sp.simplify(C.T*C)==sp.eye(C.cols)
  out+=['另算CᵀC=I，故这是正交变换；逆坐标变换为y=Cᵀx，保持长度。']
 return out

